#!/usr/bin/env node
/**
 * Tests for workflows/dev-loop.js: D2 (an unproven P2 is a note) in block readers, repeats and merges; D1 on an S lifted to M.
 * Zero dependencies — `node:test` on Node 18+; the shared harness is tools/dev-loop.harness.mjs.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS, ARGS_M, review, finding, impl, gate, NULL_GUARD, mergeReviews, classify, FILES, ROOT } from './dev-loop.harness.mjs';

test('given an L run with blocks and an unproven P2 from reader A inside the perimeter, when the block is read, then no fixer is sent it', async () => {
  // Given
  const tasks = ['T1', 'T2', 'T3', 'T4', 'T5'].map((id, i) => ({ id, title: `task ${id}`, files: ['src/Orders/OrdersQuery.cs'], dependsOn: i ? [`T${i}`] : [], tdd: false, criteria: [] }));
  const args = { ...ARGS, size: 'L', plan: { tasks }, verify: 'node --test x' };
  const bare = finding({ title: 'unproven hunch about the lookup', line: 10, evidence: undefined });

  // When
  const { calls } = await run(args, [review([], [bare]), ...Array.from({ length: 8 }, () => review([]))], Array.from({ length: 8 }, (_, i) => impl({ gate: gate('green', { tree: `t${i + 2}` }) })));

  // Then
  const sent = calls.filter(c => c.opts.agentType === 'implementer' && c.prompt.includes('unproven hunch'));
  assert.deepEqual(sent.map(c => c.opts.label), []);
});

test('given a note for an unproven P2 and the same P2 repeated with a quoted file:line next round, when the loop runs, then a fixer is sent it', async () => {
  // Given
  const args = { ...ARGS_M, verify: 'node --test x' };
  const r1 = review([], [finding({ title: NULL_GUARD, line: 10, evidence: undefined }), finding({ title: 'the total is summed twice on refunds', line: 200, evidence: 'src/Orders/OrdersQuery.cs:200 adds refund twice' })]);
  const r2 = review([{ id: 'F2', status: 'closed' }], [finding({ title: NULL_GUARD, line: 10, evidence: 'src/Orders/OrdersQuery.cs:10 dereferences order without a null check' })]);

  // When
  const { calls } = await run(args, [r1, r2], Array.from({ length: 4 }, () => impl({ gate: gate('green', { tree: '' }) })));

  // Then
  const fixes = calls.filter(c => /^fix round/.test(c.opts.label ?? ''));
  assert.ok(fixes.some(c => c.prompt.includes(NULL_GUARD)));
});

test('given two readers report the same P2, one without evidence and one quoting file:line, when mergeReviews merges them, then the kept finding is proven and blocking', () => {
  // Given
  const t = 'null guard missing on the order lookup';
  const a = { key: 'A', previous: [], found: [finding({ title: t, line: 10, evidence: undefined })] };
  const b = { key: 'B', previous: [], found: [finding({ title: t, line: 10, evidence: 'src/Orders/OrdersQuery.cs:10 dereferences order' })] };

  // When
  const merged = mergeReviews([a, b], ROOT);

  // Then
  assert.equal(merged.found.length, 1);
  assert.equal(classify(merged.found[0], FILES), 'blocking');
});

test('given a run triaged S with a risk axis and no plan, when the loop starts, then no implementer runs', async () => {
  // Given
  const args = { ...ARGS, size: 'S', risk: ['data'] };

  // When
  const { calls } = await run(args, [], [impl({})]);

  // Then
  assert.equal(calls.filter(c => c.opts.agentType === 'implementer').length, 0);
});

test('given an inline run lifted to M by a risk axis and no plan, when the loop starts, then it stops with the missing-plan question before any reader', async () => {
  // Given
  const args = { ...ARGS, size: 'S', risk: ['data'], inline: true, changed: ['src/Orders/OrdersQuery.cs'] };

  // When
  const { out, calls } = await run(args, [review([]), review([])]);

  // Then
  assert.notEqual(out.status, 'OK');
  assert.equal(calls.length, 0);
  assert.match(JSON.stringify(out), /no plan/);
});

test('given an S run lifted to M by a risk axis and no plan, when the loop starts, then the stop names the axis and offers no relaunch with size S', async () => {
  // Given
  const args = { ...ARGS, size: 'S', risk: ['security'] };

  // When
  const { out } = await run(args, [], [impl({})]);

  // Then
  const text = JSON.stringify(out);
  assert.match(text, /security/);
  assert.doesNotMatch(text, /relaunch with size S|really size S/);
});

test('given an M run with no plan and no risk lift, when the loop starts, then the stop still asks whether the change is really size S', async () => {
  // Given
  const args = { ...ARGS, size: 'M' };

  // When
  const { out } = await run(args, [], [impl({})]);

  // Then
  assert.match(JSON.stringify(out), /really size S/);
});

test('given an L run with blocks and a proven clean-code P2 from reader A inside the perimeter, when the block is read, then no fixer is sent it', async () => {
  // Given
  const tasks = ['T1', 'T2', 'T3', 'T4', 'T5'].map((id, i) => ({ id, title: `task ${id}`, files: ['src/Orders/OrdersQuery.cs'], dependsOn: i ? [`T${i}`] : [], tdd: false, criteria: [], risky: true }));
  const args = { ...ARGS, size: 'L', plan: { tasks }, verify: 'node --test x' };
  const style = finding({ title: 'naming drifts from the sibling file', category: 'clean-code', line: 10, evidence: 'src/Orders/OrdersQuery.cs:10 uses a different name' });

  // When
  const { calls } = await run(args, [review([], [style]), ...Array.from({ length: 8 }, () => review([]))], Array.from({ length: 8 }, (_, i) => impl({ gate: gate('green', { tree: `t${i + 2}` }) })));

  // Then
  const sent = calls.filter(c => c.opts.agentType === 'implementer' && c.prompt.includes('naming drifts'));
  assert.deepEqual(sent.map(c => c.opts.label), []);
});

test('given a P2 whose evidence only has a capitalised word and digits like HTTP:500, when classified, then it is a note, not a cited file:line', () => {
  // Given
  const p2 = (evidence) => finding({ priority: 'P2', category: 'logic', evidence });
  // When
  const bare = ['the handler returns HTTP:500 on an empty body', 'Status:404 is lost', 'ID:42 is reused'].map((e) => classify(p2(e), FILES, { root: ROOT }));
  // Then
  assert.deepEqual(bare, ['minor', 'minor', 'minor']);
});

test('given a P2 with evidence "Dockerfile:12 copies .env", when classified, then it counts as evidence and blocks', () => {
  // Given
  const p2 = finding({ priority: 'P2', category: 'logic', evidence: 'Dockerfile:12 copies .env' });

  // When
  const kind = classify(p2, FILES, { root: ROOT });

  // Then
  assert.equal(kind, 'blocking');
});

test('given size M with a security axis and no plan, when the loop starts, then the stop offers no relaunch as size S', async () => {
  // Given
  const args = { ...ARGS, size: 'M', risk: ['security'] };

  // When
  const { out } = await run(args, [], []);

  // Then
  assert.equal(out.status, 'STALL');
  assert.doesNotMatch(JSON.stringify(out.stall.questions), /really size S/);
  assert.match(out.stall.questions[0].text, /security/);
});
